pub fn is_stock_key(profile: i32, h: u64) -> bool {
    matches!(KEYS.binary_search_by_key(&h, |e| e.0), Ok(k) if KEYS[k].1 & 1 << profile != 0)
}

pub fn is_safe(profile: i32, h: u64) -> bool {
    matches!(SAFE.binary_search_by_key(&h, |e| e.0), Ok(k) if SAFE[k].1 & 1 << profile != 0)
}

pub fn is_known(profile: i32, h: u64) -> bool {
    matches!(KNOWN.binary_search_by_key(&h, |e| e.0), Ok(k) if KNOWN[k].1 & 1 << profile != 0)
}
